query.base:
TS metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND (`metrics.storage.googleapis.com/network/sent_bytes_count` IS NOT NULL
         OR `metrics.storage.googleapis.com/api/request_count` IS NOT NULL)
// The rule compares the last 6h ("recent") with two baselines: the 18h before them, and the same
// time of day on each of the previous 7 days, which keeps a daily or weekly job, such as an export
// or a backup, from alerting again once it has run before. The same-time window runs from 7h
// before to 1h after this time of day, so a job that starts a little earlier or later, or moves an
// hour with daylight saving time, still matches.
// same_time_day is k when the sample falls in that window on the k-th previous day, otherwise 0;
// the rule's 175h window covers day 7.
| EVAL minutes_ago   = DATE_DIFF("minutes", @timestamp, NOW()),
       same_time_day = CASE((minutes_ago + 60) % 1440 < 480, (minutes_ago + 60) / 1440, 0)
// Both metrics are ~60s delta counters stored as gauges. SUM_OVER_TIME totals each series and SUM
// adds the series together: the collector can split one bucket's metric across several series
// (_metric_names_hash is a dimension), and each sample is still counted once. Never RATE() them.
// The two do not reliably share a document, so bytes-per-request must be SUM(a)/SUM(b) in a
// single STATS and must never be computed per document with EVAL.
// Each day gets its own filtered aggregation: grouping TS results BY a computed day does not split
// the per-series totals.
| STATS recent_sent_bytes   = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE @timestamp >= NOW() - 6 hours,
        baseline_sent_bytes = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE @timestamp >= NOW() - 24 hours AND @timestamp < NOW() - 6 hours,
        day_1               = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE same_time_day == 1,
        day_2               = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE same_time_day == 2,
        day_3               = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE same_time_day == 3,
        day_4               = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE same_time_day == 4,
        day_5               = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE same_time_day == 5,
        day_6               = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE same_time_day == 6,
        day_7               = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/network/sent_bytes_count`)) WHERE same_time_day == 7,
        recent_requests     = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE @timestamp >= NOW() - 6 hours,
        baseline_requests   = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE @timestamp >= NOW() - 24 hours AND @timestamp < NOW() - 6 hours,
        recent_methods      = VALUES(attributes.method) WHERE @timestamp >= NOW() - 6 hours
    BY resource.attributes.bucket_name, resource.attributes.location
| EVAL peak_same_time_sent_bytes = GREATEST(COALESCE(day_1, 0), COALESCE(day_2, 0), COALESCE(day_3, 0), COALESCE(day_4, 0),
                                            COALESCE(day_5, 0), COALESCE(day_6, 0), COALESCE(day_7, 0))
| DROP day_1, day_2, day_3, day_4, day_5, day_6, day_7
| EVAL recent_sent_bytes = COALESCE(recent_sent_bytes, 0), baseline_sent_bytes = COALESCE(baseline_sent_bytes, 0)

breach.segment:
// Absolute floor: 32 GiB egressed in the recent slice. Set this to the point where an unexplained
// transfer is worth a human looking at it in your environment; it is the main cost-control knob.
WHERE recent_sent_bytes >= 34359738368
// 6.0, 18.0 and 8.0 are the slice widths in hours — keep them in sync with the slices above and
// timeWindowSize. Cast before dividing: the byte counters are longs and `a / b` would be integer division.
| EVAL recent_egress_gib_per_hour         = ROUND(recent_sent_bytes::DOUBLE / 1073741824.0 / 6.0, 2),
       baseline_egress_gib_per_hour       = ROUND(baseline_sent_bytes::DOUBLE / 1073741824.0 / 18.0, 2),
       peak_same_time_egress_gib_per_hour = ROUND(peak_same_time_sent_bytes::DOUBLE / 1073741824.0 / 8.0, 2)
// Context, not a condition: a jump in bytes-per-request means object sizes changed, while a flat
// bytes-per-request with far more requests means a read storm. They need different remediations.
| EVAL recent_bytes_per_request   = ROUND(recent_sent_bytes::DOUBLE / recent_requests, 0),
       baseline_bytes_per_request = ROUND(baseline_sent_bytes::DOUBLE / baseline_requests, 0)
// Step-change test on the unrounded hourly rates, against the higher of the two baselines, so the
// recent rate must be a step change on both the preceding hours and the busiest of the previous 7
// days at this time. A bucket with no egress in either baseline is compared against 1 GiB/hour
// instead, so the ratio stays finite; the volume floor above already makes such a bucket significant.
| EVAL reference_bytes_per_hour = GREATEST(baseline_sent_bytes::DOUBLE / 18.0, peak_same_time_sent_bytes::DOUBLE / 8.0)
| EVAL egress_growth_factor = ROUND((recent_sent_bytes::DOUBLE / 6.0)
      / CASE(reference_bytes_per_hour > 0, reference_bytes_per_hour, 1073741824.0), 2)
| WHERE egress_growth_factor >= 3.0
| SORT egress_growth_factor DESC
| LIMIT 50
